// Callees: 0x00497890 GFROR13 (landed, __fastcall), 0x00BFEB28 _CIfmod (the `fmod` intrinsic).
// Constants: 0x012387D8 65536.0, 0x012387D0 0.0001, 0x012387C8 2^32 (unsigned -> double fix-up), 0x012387C0
